.pod-root * { box-sizing: border-box; margin: 0; padding: 0; }
.pod-root {
  font-family: 'Pretendard', sans-serif;
  background: var(--pn-090d16, #090d16);
  color: var(--pn-f8fafc, #f8fafc);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 30px 16px;
}
.pod-root .calc-card {
  width: 100%;
  max-width: 640px;
  background: var(--pn-111827, #111827);
  border: 1px solid var(--pn-ffffff-012, rgba(255,255,255,0.12));
  border-radius: 28px;
  padding: 36px 30px;
  box-shadow: 0 25px 60px var(--pn-000000-07, rgba(0,0,0,0.7)), 0 0 30px rgba(var(--pod-accent-rgb, 56,189,248), 0.12);
}
.pod-root .badge {
  display: inline-block;
  padding: 4px 12px;
  background: rgba(var(--pod-accent-rgb, 56,189,248), 0.15);
  border: 1px solid rgba(var(--pod-accent-rgb, 56,189,248), 0.4);
  border-radius: 9999px;
  color: var(--pod-accent, #38bdf8);
  font-size: 12px;
  font-weight: 800;
  margin-bottom: 14px;
}
.pod-root h1 { font-size: 24px; font-weight: 900; margin-bottom: 8px; color: var(--pn-ffffff, #fff); }
.pod-root p.sub { font-size: 13.5px; color: var(--pt-94a3b8, #94a3b8); line-height: 1.5; margin-bottom: 24px; }
.pod-root .input-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 24px; }
@media (max-width: 500px) { .pod-root .input-grid { grid-template-columns: 1fr; } }
.pod-root .input-box { display: flex; flex-direction: column; gap: 6px; }
.pod-root .input-box label { font-size: 12.5px; font-weight: 700; color: var(--pn-cbd5e1, #cbd5e1); }
.pod-root .input-box input, .pod-root .input-box select {
  padding: 13px 14px;
  background: var(--pn-ffffff-005, rgba(255,255,255,0.05));
  border: 1.5px solid var(--pn-ffffff-01, rgba(255,255,255,0.1));
  border-radius: 12px;
  color: var(--pn-ffffff, #fff);
  font-size: 14px;
  outline: none;
  transition: border-color 0.2s;
}
.pod-root .input-box input:focus, .pod-root .input-box select:focus { border-color: var(--pod-accent, #38bdf8); }
.pod-root .res-box {
  background: rgba(var(--pod-accent-rgb, 56,189,248), 0.06);
  border: 1px solid rgba(var(--pod-accent-rgb, 56,189,248), 0.25);
  border-radius: 20px;
  padding: 22px;
  margin-top: 10px;
}
.pod-root .res-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }
.pod-root .res-row:last-child { margin-bottom: 0; padding-top: 12px; border-top: 1px dashed var(--pn-ffffff-01, rgba(255,255,255,0.1)); }
.pod-root .res-label { font-size: 13px; color: var(--pt-94a3b8, #94a3b8); font-weight: 600; }
.pod-root .res-val { font-size: 16px; font-weight: 800; color: var(--pn-ffffff, #fff); }
.pod-root .res-val.total { color: var(--pod-accent, #38bdf8); font-size: 22px; font-weight: 900; }
.pod-root .tax-badge { font-size: 11px; padding: 2px 8px; border-radius: 6px; background: var(--pn-ffffff-01, rgba(255,255,255,0.1)); margin-left: 6px; }
.pod-root .btn-lead {
  width: 100%;
  padding: 15px;
  background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%);
  color: #fff;
  border: none;
  border-radius: 14px;
  font-size: 14.5px;
  font-weight: 900;
  cursor: pointer;
  margin-top: 22px;
  box-shadow: 0 6px 20px rgba(2,132,199,0.3);
  transition: all 0.2s;
}
.pod-root .btn-lead:hover { filter: brightness(1.1); transform: translateY(-1px); }
.pod-root{min-height:0;width:100%;max-width:100%;overflow-x:hidden;}

