const RATES = { USD: 1380, JPY: 9.1, EUR: 1510 };

    function calculate() {
      const cur = document.getElementById('inpCurrency').value;
      const price = parseFloat(document.getElementById('inpPrice').value) || 0;
      const shipUsd = parseFloat(document.getElementById('inpShipping').value) || 0;
      const fee = (parseFloat(document.getElementById('inpFeeRatio').value) || 1.2) / 100;

      const rate = RATES[cur] || 1380;
      const priceKrw = (price * rate) * (1 + fee);
      const shipKrw = shipUsd * RATES.USD;

      // 미국은 $200 이하, 타 국가는 $150 이하 목록통관 면세
      let usdVal = price;
      if (cur === 'JPY') usdVal = (price * 9.1) / 1380;
      if (cur === 'EUR') usdVal = (price * 1510) / 1380;

      const threshold = (cur === 'USD') ? 200 : 150;
      const isTaxable = usdVal > threshold;

      let taxAmount = 0;
      if (isTaxable) {
        // 간이관세 대략 8% + 부가세 10% = 약 18.8%
        taxAmount = (priceKrw + shipKrw) * 0.188;
      }

      const total = priceKrw + shipKrw + taxAmount;

      document.getElementById('outWonPrice').innerText = Math.round(priceKrw).toLocaleString() + '원';
      document.getElementById('outTaxStatus').innerText = cur + ' $' + threshold + ' 초과 시 과세';
      document.getElementById('outTaxEligibility').innerText = isTaxable ? '과세 대상 (초과)' : '면세 대상 (0원)';
      document.getElementById('outTaxEligibility').style.color = isTaxable ? 'var(--pt-f87171, #f87171)' : '#34d399';
      document.getElementById('outTaxAmount').innerText = Math.round(taxAmount).toLocaleString() + '원';
      document.getElementById('outTotalPrice').innerText = Math.round(total).toLocaleString() + '원';
    }
    calculate();
